'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE=(process.env.P14_BASE_URL||'https://plan-ex.ru/erpv2/').replace(/\/+$/,'/'),U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P14_OUT_DIR||'P14_output');fs.mkdirSync(OUT,{recursive:true});
function cred(){const e=process.env.P11_CREDENTIALS_B64||'';const a=e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[];return a.find(x=>String(x?.role||'').toUpperCase()==='OWNER')}
async function login(c){const x=await chromium.launch({headless:true}),ctx=await x.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await ctx.newPage();await p.goto(U('login'),{waitUntil:'domcontentloaded'});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(c.username);await p.locator('input[type="password"]').fill(c.password);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(700);return{x,ctx,p}}
async function schema(p){return p.evaluate(()=>[...document.forms].filter(f=>{const r=f.getBoundingClientRect();return r.width>1&&r.height>1}).map(f=>({id:f.id||null,action:f.action,method:f.method.toUpperCase(),fields:[...f.querySelectorAll('input,select,textarea')].filter(e=>e.type!=='hidden').map(e=>({name:e.name||null,id:e.id||null,type:e.type||null,required:!!e.required,accept:e.accept||null,options:e.tagName==='SELECT'?[...e.options].map(o=>({value:o.value,text:(o.textContent||'').trim()})):null})),buttons:[...f.querySelectorAll('button,input[type="submit"]')].map(b=>(b.textContent||b.value||'').trim())})))}
(async()=>{const r={status:'FAIL',routeExecutor:null,vehicleSingle:null,clientDocument:null,error:null};let s;try{const c=cred();if(!c)throw Error('owner unavailable');s=await login(c);const p=s.p;await p.goto(U('company/route-executors'),{waitUntil:'domcontentloaded'});const b=p.locator('button,a').filter({hasText:/создать|добавить/i}).first();if(await b.count()){await b.click();await p.waitForTimeout(800)}r.routeExecutor=await schema(p);await p.screenshot({path:path.join(OUT,'P14_ROUTE_EXECUTOR_MODAL_1920x1080.png'),fullPage:false});await p.goto(U('company/vehicle-sets'),{waitUntil:'domcontentloaded'});const vb=p.locator('button,a').filter({hasText:/создать|добавить/i}).first();if(await vb.count()){await vb.click();await p.waitForTimeout(500)}const sf=p.locator('form#vehicle-set-create-form').first();if(await sf.count()){const sel=sf.locator('[name="set_type"]');await sel.selectOption('single');await p.waitForTimeout(800)}r.vehicleSingle=await schema(p);await p.screenshot({path:path.join(OUT,'P14_VEHICLE_SINGLE_MODAL_1920x1080.png'),fullPage:false});await p.goto(U('company/clients'),{waitUntil:'domcontentloaded'});const first=p.locator('a[href*="/company/clients/"]').first();if(await first.count()){await first.click();await p.waitForTimeout(700);const db=p.locator('button,a').filter({hasText:/добавить документ/i}).first();if(await db.count()){await db.click();await p.waitForTimeout(700)}}r.clientDocument=await schema(p);await p.screenshot({path:path.join(OUT,'P14_CLIENT_DOCUMENT_MODAL_1920x1080.png'),fullPage:false});r.status='PASS'}catch(e){r.error={name:e?.name||'Error',message:String(e?.message||e).slice(0,500)}}finally{if(s){await s.ctx.close().catch(()=>{});await s.x.close().catch(()=>{})}fs.writeFileSync(path.join(OUT,'P14_runtime_result.json'),JSON.stringify(r,null,2));console.log(`P14_CONTRACT_DISCOVERY=${r.status}`);process.exitCode=r.status==='PASS'?0:1}})();
